  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP turned precision measurements of the cosmic microwave background into a quantitative account of the universe's age, composition, and history. This is a major experimental achievement with enduring consequences for cosmology.",
        "attribution": "Bennett and Page were central to the instrument and measurement program, while Spergel made key contributions to cosmological interpretation. The proposed group captures complementary work, though the mission's broader team also deserves recognition.",
        "maturity": "The results have been tested against later CMB and cosmological observations over many years.",
        "uncertainties": [
          "The boundary between WMAP's specific contribution and the wider progression of CMB cosmology needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established a new observational window on the high-energy universe by detecting astrophysical neutrinos. It is a clear discovery that connects particle physics with astronomy.",
        "attribution": "Halzen's long leadership and scientific role in conceiving and advancing IceCube are substantial. The result depended on a large collaboration, so individual attribution requires particular care.",
        "maturity": "The astrophysical origin of the signal has been supported by an expanding body of data and source observations.",
        "uncertainties": [
          "The credit attributable to one individual versus the detector collaboration and other early contributors is difficult to settle."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser was a distinctive semiconductor laser invention that opened access to important infrared wavelengths and enabled broad research and practical applications.",
        "attribution": "Cho's foundational semiconductor heterostructure work, Capasso's conception and device development, and Faist's leading role in the first realization form a plausible set of complementary contributions.",
        "maturity": "The device principle has been repeatedly demonstrated and developed into a mature technology used in laboratories and applications.",
        "uncertainties": [
          "The relative credit for conception, design, and first experimental realization should be checked against the original papers and laboratory record."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed atomic frequency standards, enabling extraordinary precision and new tests of fundamental physics. The invention has also made timekeeping a sensitive probe of gravity and variation.",
        "attribution": "Katori and Ye independently developed leading realizations of the optical lattice clock; recognizing both reflects the parallel experimental advances that established the method.",
        "maturity": "The principle is now exceptionally well confirmed, with clock performance repeatedly improved by independent laboratories.",
        "uncertainties": [
          "The committee would need to define which elements of the broad precision-measurement impact are most directly attributable to the original clock invention."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance made magnetic tunnel junctions practical for devices and became a major foundation of spintronics and modern data storage.",
        "attribution": "Moodera, Parkin, and Miyazaki led independent experimental demonstrations that established the effect at technologically relevant temperatures. The parallel priority claims should be represented accurately.",
        "maturity": "The phenomenon is robust, well understood, and central to established technologies.",
        "uncertainties": [
          "The precise priority and distinct contribution of each group in the closely timed demonstrations require careful comparison of dates and results."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault-tolerant computation supplied the conceptual tools showing that quantum information can be protected against physical errors. This changed the field's understanding of what quantum computers could be.",
        "attribution": "Kitaev, Steane, and Shor made foundational, distinct contributions to topological protection, quantum error-correcting codes, and the threshold framework.",
        "maturity": "The theoretical foundations are established, and experimental systems increasingly demonstrate key ingredients, although large-scale fault-tolerant computing remains unrealized.",
        "uncertainties": [
          "The eventual scale and practical reach of fault-tolerant quantum computation remain uncertain.",
          "A full attribution may need to account for foundational work beyond these three figures."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulators and the quantum spin Hall effect revealed a new class of quantum matter, with deep consequences for condensed matter physics.",
        "attribution": "Kane and Mele provided decisive theoretical predictions, and Molenkamp's experiments demonstrated the quantum spin Hall effect. This links prediction to a consequential measurement.",
        "maturity": "The topological framework is now well established across many systems, although identifying and isolating the original decisive steps matters for credit.",
        "uncertainties": [
          "The transition from the initial quantum spin Hall demonstration to the broader topological-insulator field involves additional experimental contributions."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "Kilonovae connect neutron-star mergers to heavy-element production and multi-messenger astronomy. Their observation supplied a striking test of predictions about a violent astrophysical process.",
        "attribution": "Metzger and Kasen made important theoretical contributions to the predicted emission and interpretation; Tanvir contributed to the observational discovery. The proposed set spans prediction and observation.",
        "maturity": "The merger and its electromagnetic counterpart were observed, but the field is still building its sample and refining how much of the heavy-element abundance can be assigned to these events.",
        "uncertainties": [
          "The continuing observational record may change the assessment of how general the proposed production mechanism is.",
          "Credit for the discovery and interpretation is distributed across a large international effort."
        ]
      }
    }
  ]
}
